1	// Cascades a soft delete down the workflow chain: Schedule -> Inspection -> Defect ->
2	// Rectification. Each step of the chain is optional-by-design (an Inspection can exist
3	// without a Schedule, a Defect without an Inspection - see the model comments), so
4	// cascading only ever touches records that actually declared the link, and only ever
5	// flips `isDeleted` (never a hard delete) so the audit trail stays intact and reversible.
6	const Inspection = require('../models/inspections/Inspection');
7	const Defect = require('../models/defects/Defect');
8	const Rectification = require('../models/rectifications/Rectification');
9	
10	// Soft-deletes every Rectification pointing at any of the given defect ids.
11	async function cascadeFromDefects(defectIds) {
12	  if (!defectIds || !defectIds.length) return { rectifications: 0 };
13	  const { modifiedCount } = await Rectification.updateMany(
14	    { defectId: { $in: defectIds }, isDeleted: false },
15	    { isDeleted: true }
16	  );
17	  return { rectifications: modifiedCount };
18	}
19	
20	// Soft-deletes every standalone Defect raised by any of the given inspection ids, then
21	// cascades further down to any Rectification against those defects.
22	async function cascadeFromInspections(inspectionIds) {
23	  if (!inspectionIds || !inspectionIds.length) return { defects: 0, rectifications: 0 };
24	
25	  const defectIds = await Defect.find(
26	    { inspectionId: { $in: inspectionIds }, isDeleted: false },
27	    '_id'
28	  ).distinct('_id');
29	
30	  const { modifiedCount } = await Defect.updateMany(
31	    { inspectionId: { $in: inspectionIds }, isDeleted: false },
32	    { isDeleted: true }
33	  );
34	
35	  const deeper = await cascadeFromDefects(defectIds);
36	  return { defects: modifiedCount, ...deeper };
37	}
38	
39	// Soft-deletes every Inspection that followed up on the given schedule, then cascades
40	// further down through the Defects and Rectifications those inspections led to. Called
41	// right after a Schedule is itself soft-deleted.
42	async function cascadeFromSchedule(scheduleId) {
43	  const inspectionIds = await Inspection.find(
44	    { scheduleId, isDeleted: false },
45	    '_id'
46	  ).distinct('_id');
47	
48	  const { modifiedCount } = await Inspection.updateMany(
49	    { scheduleId, isDeleted: false },
50	    { isDeleted: true }
51	  );
52	
53	  const deeper = await cascadeFromInspections(inspectionIds);
54	  return { inspections: modifiedCount, ...deeper };
55	}
56	
57	// Repair pass, safe to re-run at any time: (1) backfills `isDeleted: false` onto any
58	// legacy documents saved before that field existed (a plain MongoDB equality filter like
59	// `{ isDeleted: false }` does NOT match a document where the field is simply absent, so
60	// without this those old records would silently disappear from every list/get endpoint),
61	// then (2) soft-deletes any Defect/Inspection/Rectification left dangling because its
62	// parent was removed by something other than the cascading delete handlers above (e.g. a
63	// direct database edit, or data seeded before a link field existed).
64	async function cleanupOrphans() {
65	  const Schedule = require('../models/scheduling/Schedule');
66	
67	  const backfill = await Promise.all([
68	    Inspection.updateMany({ isDeleted: { $exists: false } }, { isDeleted: false }),
69	    Defect.updateMany({ isDeleted: { $exists: false } }, { isDeleted: false }),
70	  ]);
71	
72	  const orphanedInspectionIds = await Inspection.find({
73	    isDeleted: false,
74	    scheduleId: { $ne: null },
75	  })
76	    .then(async (inspections) => {
77	      const scheduleIds = inspections.map((i) => i.scheduleId).filter(Boolean);
78	      const liveSchedules = await Schedule.find({ _id: { $in: scheduleIds }, isDeleted: false }, '_id').distinct(
79	        '_id'
80	      );
81	      const liveSet = new Set(liveSchedules.map(String));
82	      return inspections.filter((i) => !liveSet.has(String(i.scheduleId))).map((i) => i._id);
83	    });
84	  await Inspection.updateMany({ _id: { $in: orphanedInspectionIds } }, { isDeleted: true });
85	
86	  const orphanedDefectIds = await Defect.find({
87	    isDeleted: false,
88	    inspectionId: { $ne: null },
89	  })
90	    .then(async (defects) => {
91	      const inspectionIds = defects.map((d) => d.inspectionId).filter(Boolean);
92	      const liveInspections = await Inspection.find(
93	        { _id: { $in: inspectionIds }, isDeleted: false },
94	        '_id'
95	      ).distinct('_id');
96	      const liveSet = new Set(liveInspections.map(String));
97	      return defects.filter((d) => !liveSet.has(String(d.inspectionId))).map((d) => d._id);
98	    });
99	  await Defect.updateMany({ _id: { $in: orphanedDefectIds } }, { isDeleted: true });
100	
101	  const orphanedRectifications = await Rectification.find({ isDeleted: false }).then(async (rects) => {
102	    const defectIds = rects.map((r) => r.defectId).filter(Boolean);
103	    const liveDefects = await Defect.find({ _id: { $in: defectIds }, isDeleted: false }, '_id').distinct('_id');
104	    const liveSet = new Set(liveDefects.map(String));
105	    return rects.filter((r) => !liveSet.has(String(r.defectId))).map((r) => r._id);
106	  });
107	  await Rectification.updateMany({ _id: { $in: orphanedRectifications } }, { isDeleted: true });
108	
109	  return {
110	    backfilled: { inspections: backfill[0].modifiedCount, defects: backfill[1].modifiedCount },
111	    orphaned: {
112	      inspections: orphanedInspectionIds.length,
113	      defects: orphanedDefectIds.length,
114	      rectifications: orphanedRectifications.length,
115	    },
116	  };
117	}
118	
119	module.exports = { cascadeFromSchedule, cascadeFromInspections, cascadeFromDefects, cleanupOrphans };
120

