11	
12	// GET /api/scheduling
13	// Supports optional ?status=Scheduled, ?date=2026-08-06 and ?liftId=<id> filters so the
14	// frontend can drive "what's due" views and lift-scoped views without extra endpoints.
15	// Staff callers are additionally scoped to only their own assigned schedules - Admin/Master
16	// see everything, unfiltered by this dimension.
17	const listSchedules = asyncHandler(async (req, res) => {
18	  const { status, date, liftId } = req.query;
19	  const filter = { isDeleted: false };
20	
21	  if (status) {
22	    filter.status = status;
23	  }
24	
25	  if (liftId) {
26	    filter.liftId = liftId;
27	  }
28	
29	  if (date) {
30	    const start = new Date(date);
31	    const end = new Date(date);
32	    end.setDate(end.getDate() + 1);
33	    filter.scheduledDate = { $gte: start, $lt: end };
34	  }
35	
36	  if (req.user.role === 'Staff') {
37	    filter.assignedStaffId = req.user._id;
38	  }
39	
40	  const schedules = await Schedule.find(filter).sort({ scheduledDate: 1 });
41	  ok(res, schedules);
42	});
