44	// GET /api/scheduling/:id
45	// A Staff user gets a 404 (not 403) for a schedule not assigned to them - same as
46	// "not found" rather than revealing that a schedule exists but isn't theirs. Without this,
47	// a Staff user could bypass the list-level scoping above by guessing/copying another
48	// schedule's id directly.
49	const getSchedule = asyncHandler(async (req, res) => {
50	  const schedule = await Schedule.findOne({ _id: req.params.id, isDeleted: false }).catch(() => null);
51	  if (!schedule) throw ApiError.notFound('Schedule not found');
52	
53	  if (req.user.role === 'Staff' && String(schedule.assignedStaffId) !== String(req.user._id)) {
54	    throw ApiError.notFound('Schedule not found');
55	  }
56	
57	  ok(res, schedule);
58	});
