60	// POST /api/scheduling
61	// Route-level requireRole('Admin','Master') already keeps Staff out entirely - no
62	// role-branching needed here.
63	const createSchedule = asyncHandler(async (req, res) => {
64	  const { townCouncil, liftCompany, blockAddress, scheduledDate, assignedInspector, assignedStaffId, notes, liftId } =
65	    req.body;
66	
67	  if (!townCouncil || !liftCompany || !blockAddress || !scheduledDate) {
68	    throw ApiError.badRequest('townCouncil, liftCompany, blockAddress and scheduledDate are required');
69	  }
70	
71	  const schedule = await Schedule.create({
72	    townCouncil,
73	    liftCompany,
74	    blockAddress,
75	    scheduledDate,
76	    assignedInspector,
77	    assignedStaffId: assignedStaffId || null,
78	    notes,
79	    liftId: liftId || null,
80	  });
81	
82	  ok(res, schedule, 'Schedule created', 201);
83	});
84	
85	// PUT /api/scheduling/:id
86	// Handles both field edits and status transitions (Scheduled -> Assigned -> ...) from the
87	// same endpoint so the frontend can PATCH-like update with a partial body.
88	// Admin/Master: full-field update, same as before. Staff: only allowed on their own
89	// assigned schedule, and only the `status` field may be present in the body - any other
90	// key is rejected outright.
91	const updateSchedule = asyncHandler(async (req, res) => {
92	  const existing = await Schedule.findOne({ _id: req.params.id, isDeleted: false }).catch(() => null);
93	  if (!existing) throw ApiError.notFound('Schedule not found');
94	
95	  let updates;
96	  if (req.user.role === 'Staff') {
97	    if (String(existing.assignedStaffId) !== String(req.user._id)) {
98	      throw ApiError.notFound('Schedule not found');
99	    }
100	
101	    const disallowedKeys = Object.keys(req.body).filter((key) => key !== 'status');
102	    if (disallowedKeys.length) {
103	      throw ApiError.forbidden(`Staff can only update the status field (rejected: ${disallowedKeys.join(', ')})`);
104	    }
105	
106	    updates = { status: req.body.status };
107	  } else {
108	    updates = { ...req.body };
109	  }
110	
111	  if (updates.status && !Schedule.STATUS_VALUES.includes(updates.status)) {
112	    throw ApiError.badRequest(`status must be one of ${Schedule.STATUS_VALUES.join(', ')}`);
113	  }
114	
115	  const schedule = await Schedule.findOneAndUpdate({ _id: req.params.id, isDeleted: false }, updates, {
116	    new: true,
117	    runValidators: true,
118	  });
119	
120	  if (!schedule) throw ApiError.notFound('Schedule not found');
121	
122	  ok(res, schedule);
123	});
124	
125	// DELETE /api/scheduling/:id  (soft delete — keeps audit trail per data-integrity feedback)
126	// Cascades: soft-deleting a schedule also soft-deletes every inspection that followed up
127	// on it, and in turn every defect/rectification those inspections led to - a schedule is
128	// the root of the workflow chain, so removing it should remove what it produced instead
129	// of leaving orphaned downstream records behind (see utils/cascadeDelete.js).
130	// Route-level requireRole('Admin','Master') already keeps Staff out entirely.
131	const deleteSchedule = asyncHandler(async (req, res) => {
132	  const schedule = await Schedule.findOneAndUpdate(
133	    { _id: req.params.id, isDeleted: false },
134	    { isDeleted: true },
135	    { new: true }
136	  );
137	
138	  if (!schedule) throw ApiError.notFound('Schedule not found');
139	
140	  const cascaded = await cascadeFromSchedule(schedule._id);
141	  ok(res, { id: schedule._id, cascaded }, 'Schedule deleted');
142	});
