310	          </Box>
311	          <Stack direction="row" spacing={1}>
312	            <StatusChip value={report.compliance} colorMap={DEFECT_COMPLIANCE_COLORS} />
313	            <StatusChip value={report.overallStatus} colorMap={INSPECTION_STATUS_COLORS} />
