321	          <Grid item xs={6} sm={3}><Field label="Contractor Notified" value={report.contractorNotifiedAt ? formatDate(report.contractorNotifiedAt) : 'Not yet notified'} /></Grid>
322	        </Grid>
323	        {report.notes && <><Divider sx={{ my: 2 }} /><Field label="Notes" value={report.notes} /></>}
324	      </Paper>
325	
326	      <Paper variant="outlined" sx={{ p: 3, mb: 3 }}>
327	        <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>Inspection Checklist</Typography>
328	        <Table size="small">
329	          <TableHead><TableRow><TableCell>Item</TableCell><TableCell width={100}>Result</TableCell><TableCell>Remarks</TableCell></TableRow></TableHead>
330	          <TableBody>
331	            {(report.checklist || []).map((c, i) => (
332	              <TableRow key={i}>
333	                <TableCell>{c.item}</TableCell>
334	                <TableCell>
335	                  <Chip size="small" label={c.result} color={c.result === 'Fail' ? 'error' : c.result === 'Pass' ? 'success' : 'default'} />
336	                </TableCell>
337	                <TableCell>{c.remarks || '—'}</TableCell>
338	              </TableRow>
339	            ))}
340	          </TableBody>
341	        </Table>
342	      </Paper>
343	
344	      <Paper variant="outlined" sx={{ p: 3 }}>
345	        <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>Defects Found</Typography>
346	        {(!report.defects || report.defects.length === 0) ? (
347	          <Typography variant="body2" color="text.secondary">No defects logged on this report.</Typography>
348	        ) : (
349	          <Stack spacing={2}>
350	            {report.defects.map((d) => (
351	              <Paper key={d._id} variant="outlined" sx={{ p: 2 }}>
352	                <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}>
353	                  {d.photoUrl && (
354	                    <Avatar variant="rounded" src={d.photoUrl} sx={{ width: 72, height: 72, cursor: 'pointer', flexShrink: 0 }} onClick={() => setPreviewUrl(d.photoUrl)} />
355	                  )}
356	                  <Box sx={{ flex: 1 }}>
357	                    <Typography variant="body1">{d.description}</Typography>
358	                    <Stack direction="row" spacing={1} sx={{ mt: 0.5 }}>
359	                      <StatusChip value={d.severity} colorMap={DEFECT_SEVERITY_COLORS} />
360	                      <Chip size="small" label={d.status} variant="outlined" />
361	                    </Stack>
362	                    {d.raisedDate && <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>Raised {formatDate(d.raisedDate)}</Typography>}
363	                  </Box>
364	                </Stack>
365	              </Paper>
366	            ))}
367	          </Stack>
368	        )}
369	      </Paper>
370	
371	      <Dialog open={Boolean(previewUrl)} onClose={() => setPreviewUrl(null)} maxWidth="md">
372	        {previewUrl && (
373	          <Box sx={{ position: 'relative', bgcolor: 'black', display: 'flex', justifyContent: 'center' }}>
374	            <IconButton size="small" onClick={() => setPreviewUrl(null)} sx={{ position: 'absolute', top: 8, right: 8, bgcolor: 'rgba(255,255,255,0.85)' }}><CloseIcon fontSize="small" /></IconButton>
375	            <img src={previewUrl} alt="Defect photo" style={{ maxWidth: '100%', maxHeight: '80vh', display: 'block' }} />
376	          </Box>
377	        )}
378	      </Dialog>
379	    </Box>
380	  );
381	}
