      field: 'severity',
      headerName: 'Severity',
      width: 120,
      renderCell: (params) => <StatusChip value={params.value} colorMap={DEFECT_SEVERITY_COLORS} />,
    },
    {
      field: 'status',
      headerName: 'Status',
      width: 130,
      renderCell: (params) => <StatusChip value={params.value} colorMap={DEFECT_STATUS_COLORS} />,
    },
    {
      field: 'reportedDate',
      headerName: 'Reported',
      width: 120,
      renderCell: (params) => formatDate(params.value),
    },
    {
      field: 'actions',
      headerName: 'Actions',
      width: canEdit ? 100 : 40,
      sortable: false,
      filterable: false,
      renderCell: (params) =>
        canEdit ? (
          <Stack direction="row">
            <IconButton
              size="small"
              title="Edit defect"
              onClick={() => {
                setEditingDefect(params.row);
                setFormOpen(true);
              }}
